  commit.type = Preserve_trx_transfer_frame_type::COMMIT_EPOCH;
  commit.sequence = 19;
  commit.epoch_id =
      preserve_trx_transfer_make_epoch_id_for_unit_test("abandon-outcome");
  commit.token = 829;
  commit.chunk_offset = 140;
  commit.terminal_fact_digest[0] = 0x7b;
