TEST_F(PreserveSnapshotTest,
       TransferReceiverExactCommitRetryResendsAcceptedAck) {
  Transfer_codec_context_guard codec_guard;
  Transfer_receiver_config_guard receiver_config;
  receiver_config.allow();

  Preserve_snapshot_metadata meta = metadata();
  meta.token = test_transfer_token_string(916);
  Preserved_trx_bundle bundle;
  Preserved_trx_bundle_build_input input;
  input.metadata = meta;
  input.emit_no_cache_binlog_mode_metadata = true;
  ASSERT_EQ(Preserve_snapshot_status::OK,
            build_preserved_trx_bundle(input, &bundle));

  Capturing_transfer_frame_sink sink;
  Preserve_trx_transfer_source_epoch_session session(
      "epoch-source-session-commit-ack-retry", 11, &sink);
  ASSERT_EQ(Preserve_trx_transfer_status::OK, session.declare_token(916));
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            session.send_token_bundle(bundle, 916));
  ASSERT_EQ(Preserve_trx_transfer_status::OK, session.commit_epoch());

  Local_file_preserved_trx_carrier carrier(m_dir);
  Preserved_trx_store store(&carrier);
  Preserve_trx_transfer_receiver_registry registry;
  Transfer_receiver_commit_accepted_probe probe;
  probe.root_dir = m_dir;
  probe.epoch_id = "epoch-source-session-commit-ack-retry";
  probe.registry = &registry;
  probe.return_statuses = {Preserve_trx_transfer_status::ACK_UNCERTAIN,
                           Preserve_trx_transfer_status::OK};

  ASSERT_GT(sink.frames().size(), 1U);
  const uint64_t seal_ready_before =
      preserve_trx_transfer_receiver_seal_prewarm_success_tokens_status();
  const std::vector<std::string> phase1_frames(sink.frames().begin(),
                                                sink.frames().end() - 1);
  const std::vector<std::string> commit_frame{sink.frames().back()};
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_handle_receiver_payload_batch(
                m_dir, phase1_frames, &store, &registry, 300, 3));
  for (uint attempt = 0; attempt < 100; ++attempt) {
    if (preserve_trx_transfer_receiver_seal_prewarm_success_tokens_status() >
        seal_ready_before) {
      break;
    }
    my_sleep(10000);
  }
  ASSERT_GT(preserve_trx_transfer_receiver_seal_prewarm_success_tokens_status(),
            seal_ready_before);

  EXPECT_EQ(Preserve_trx_transfer_status::ACK_UNCERTAIN,
            preserve_trx_transfer_handle_receiver_payload_batch(
                m_dir, commit_frame, &store, &registry, 300, 3, nullptr,
                nullptr, nullptr, transfer_receiver_commit_accepted_probe,
                &probe));
  EXPECT_EQ(Preserve_trx_transfer_epoch_terminal_outcome::COMMITTED,
            registry.query_epoch_terminal(
                m_dir, "epoch-source-session-commit-ack-retry"));
  Preserve_trx_transfer_accepted_epoch accepted;
  ASSERT_EQ(Preserve_trx_transfer_status::COMMITTED_NOT_READY,
            registry.query_accepted_epoch(
                m_dir, "epoch-source-session-commit-ack-retry", &accepted));
  EXPECT_EQ(Preserve_trx_transfer_epoch_lifecycle::PREWARMING,
            accepted.lifecycle);

  EXPECT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_handle_receiver_payload_batch(
                m_dir, commit_frame, &store, &registry, 300, 3, nullptr,
                nullptr, nullptr, transfer_receiver_commit_accepted_probe,
                &probe));
  EXPECT_EQ(2U, probe.call_count);
  EXPECT_EQ(Preserve_trx_transfer_epoch_terminal_outcome::COMMITTED,
            registry.query_epoch_terminal(
                m_dir, "epoch-source-session-commit-ack-retry"));
  ASSERT_EQ(Preserve_trx_transfer_status::COMMITTED_NOT_READY,
            registry.query_accepted_epoch(
                m_dir, "epoch-source-session-commit-ack-retry", &accepted));
  EXPECT_EQ(Preserve_trx_transfer_epoch_lifecycle::READY, accepted.lifecycle);
}

TEST_F(PreserveSnapshotTest,
       TransferReceiverCommitWaitsForPriorSavedPayloadSemanticApply) {
  Transfer_receiver_config_guard receiver_config;
  receiver_config.allow();
  Local_file_preserved_trx_carrier carrier(m_dir);
  Preserved_trx_store store(&carrier);
  Preserve_trx_transfer_receiver_registry registry;

  Preserve_trx_transfer_frame declare;
  declare.type = Preserve_trx_transfer_frame_type::DECLARE_TOKEN;
  declare.sequence = 1;
  declare.epoch_id = "epoch-commit-apply-barrier";
  declare.token = 918;
  std::string encoded_declare;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_encode_frame(declare, &encoded_declare));

  Preserve_trx_transfer_frame commit;
  commit.type = Preserve_trx_transfer_frame_type::COMMIT_EPOCH;
  commit.sequence = 2;
  commit.epoch_id = declare.epoch_id;
  commit.token = declare.token;
  std::string encoded_commit;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_encode_frame(commit, &encoded_commit));

  Transfer_receiver_blocking_after_admission_probe probe;
  std::atomic<int> declare_status{
      static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN)};
  std::thread declare_thread([&] {
    declare_status.store(static_cast<int>(
        preserve_trx_transfer_handle_receiver_payload_batch(
            m_dir, {encoded_declare}, &store, &registry, 1, 1, nullptr,
            transfer_receiver_blocking_after_admission_probe, &probe)));
  });
  {
    std::unique_lock<std::mutex> lock(probe.mutex);
    ASSERT_TRUE(probe.condition.wait_for(
        lock, std::chrono::seconds(1), [&] { return probe.entered; }));
  }

  std::atomic<int> commit_status{
      static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN)};
  std::thread commit_thread([&] {
    commit_status.store(static_cast<int>(
        preserve_trx_transfer_handle_receiver_payload_batch(
            m_dir, {encoded_commit}, &store, &registry, 1, 1)));
  });
  my_sleep(20000);
  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN),
            commit_status.load());

  {
    std::lock_guard<std::mutex> lock(probe.mutex);
    probe.released = true;
  }
  probe.condition.notify_all();
  declare_thread.join();
  commit_thread.join();
  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::OK),
            declare_status.load());
  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::CORRUPT),
            commit_status.load());
}

TEST_F(PreserveSnapshotTest,
       TransferReceiverAbandonWaitsForInFlightPayloadSemanticApply) {
  Transfer_receiver_config_guard receiver_config;
  receiver_config.allow();
  Local_file_preserved_trx_carrier carrier(m_dir);
  Preserved_trx_store store(&carrier);
  Preserve_trx_transfer_receiver_registry registry;
  const std::string epoch_id = "epoch-abandon-apply-barrier";
  const std::string principal = "17:preserve_transfer|1:%";
  const std::string nonce = "00112233445566778899aabbccddeeff";
  uint64_t accepted_retention_us = 0;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            registry.open_online_epoch(epoch_id, principal, 60000000, nonce,
                                       &accepted_retention_us));

  Preserve_trx_transfer_manifest existing;
  existing.epoch_id = epoch_id;
  existing.token = 1918;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            registry.begin_receive(existing));

  Preserve_trx_transfer_frame declare;
  declare.type = Preserve_trx_transfer_frame_type::DECLARE_TOKEN;
  declare.sequence = 1;
  declare.epoch_id = epoch_id;
  declare.receiver_process_nonce = nonce;
  declare.token = 1919;
  std::string encoded_declare;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_encode_frame(declare, &encoded_declare));

  Transfer_receiver_blocking_after_admission_probe probe;
  std::atomic<int> declare_status{
      static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN)};
  std::thread declare_thread([&] {
    declare_status.store(static_cast<int>(
        preserve_trx_transfer_handle_receiver_payload_batch(
            m_dir, {encoded_declare}, &store, &registry, 1, 1, nullptr,
            transfer_receiver_blocking_after_admission_probe, &probe)));
  });
  {
    std::unique_lock<std::mutex> lock(probe.mutex);
    ASSERT_TRUE(probe.condition.wait_for(
        lock, std::chrono::seconds(1), [&] { return probe.entered; }));
  }

  Preserve_trx_transfer_epoch_terminal_request abandon;
  abandon.root_dir = m_dir;
  abandon.epoch_id = epoch_id;
  abandon.receiver_process_generation = nonce;
  abandon.authenticated_principal = principal;
  abandon.operation_id = "abandon-inflight-apply";
  abandon.fact_digest = test_sha256("abandon-inflight-apply");
  abandon.now_us = 1000;
  abandon.retention_us = accepted_retention_us;
  EXPECT_EQ(Preserve_trx_transfer_epoch_terminal_outcome::NOT_COMMITTED,
            preserve_trx_transfer_abandon_receiver_epoch_if_not_committed(
                abandon, &registry));

  {
    std::lock_guard<std::mutex> lock(probe.mutex);
    probe.released = true;
  }
  probe.condition.notify_all();
  declare_thread.join();
  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::OK),
            declare_status.load());

  Preserve_trx_transfer_receiver_record record;
  EXPECT_TRUE(registry.lookup(epoch_id, existing.token, &record));
  EXPECT_TRUE(registry.lookup(epoch_id, declare.token, &record));
}

TEST_F(PreserveSnapshotTest,
       TransferReceiverSameTokenPayloadWaitsForEarlierSemanticApply) {
  Transfer_codec_context_guard codec_guard;
  Transfer_receiver_config_guard receiver_config;
  receiver_config.allow();
  const uint64_t token = 919;

  Preserve_snapshot_metadata meta = metadata();
  meta.token = test_transfer_token_string(token);
  Preserved_trx_bundle bundle;
  Preserved_trx_bundle_build_input input;
  input.metadata = meta;
  ASSERT_EQ(Preserve_snapshot_status::OK,
            build_preserved_trx_bundle(input, &bundle));

  Preserve_trx_transfer_manifest manifest;
  std::vector<Preserve_trx_transfer_object_payload> objects;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_build_portable_objects(
                "epoch-same-token-apply-barrier", bundle, token, &manifest, &objects));
  ASSERT_FALSE(objects.empty());

  std::string manifest_payload;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_encode_manifest(manifest,
                                                  &manifest_payload));

  Preserve_trx_transfer_frame begin;
  begin.type = Preserve_trx_transfer_frame_type::BEGIN;
  begin.sequence = 1;
  begin.epoch_id = manifest.epoch_id;
  begin.token = token;
  begin.manifest_payload = manifest_payload;

  Preserve_trx_transfer_frame chunk;
  chunk.type = Preserve_trx_transfer_frame_type::OBJECT_CHUNK;
  chunk.sequence = 2;
  chunk.epoch_id = manifest.epoch_id;
  chunk.token = token;
  chunk.object_id = objects.front().descriptor.object_id;
  chunk.chunk_payload = objects.front().payload;

  Preserve_trx_transfer_frame seal;
  seal.type = Preserve_trx_transfer_frame_type::SEAL_OBJECT;
  seal.sequence = 3;
  seal.epoch_id = manifest.epoch_id;
  seal.token = token;
  seal.object_id = chunk.object_id;

  std::vector<std::string> first_payload;
  for (const Preserve_trx_transfer_frame *frame : {&begin, &chunk}) {
    std::string encoded;
    ASSERT_EQ(Preserve_trx_transfer_status::OK,
              preserve_trx_transfer_encode_frame(*frame, &encoded));
    first_payload.push_back(std::move(encoded));
  }
  std::string encoded_seal;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_encode_frame(seal, &encoded_seal));

  Local_file_preserved_trx_carrier carrier(m_dir);
  Preserved_trx_store store(&carrier);
  Preserve_trx_transfer_receiver_registry registry;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            registry.declare_token(manifest.epoch_id, token));

  Transfer_receiver_blocking_after_admission_probe probe;
  std::atomic<int> first_status{
      static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN)};
  std::thread first_thread([&] {
    first_status.store(static_cast<int>(
        preserve_trx_transfer_handle_receiver_payload_batch(
            m_dir, first_payload, &store, &registry, 1, 1, nullptr,
            transfer_receiver_blocking_after_admission_probe, &probe)));
  });
  {
    std::unique_lock<std::mutex> lock(probe.mutex);
    ASSERT_TRUE(probe.condition.wait_for(
        lock, std::chrono::seconds(1), [&] { return probe.entered; }));
  }

  std::atomic<int> seal_status{
      static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN)};
  std::thread seal_thread([&] {
    seal_status.store(static_cast<int>(
        preserve_trx_transfer_handle_receiver_payload_batch(
            m_dir, {encoded_seal}, &store, &registry, 1, 1)));
  });
  my_sleep(20000);
  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN),
            seal_status.load());

  {
    std::lock_guard<std::mutex> lock(probe.mutex);
    probe.released = true;
  }
  probe.condition.notify_all();
  first_thread.join();
  seal_thread.join();

  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::OK),
            first_status.load());
  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::OK),
            seal_status.load());
  Preserve_trx_transfer_receiver_record record;
  ASSERT_TRUE(registry.lookup(manifest.epoch_id, token, &record));
  EXPECT_EQ(1U, record.sealed_objects.count(chunk.object_id));
}

TEST_F(PreserveSnapshotTest,
       TransferReceiverDifferentTokenPayloadDoesNotWaitForSemanticApply) {
  Transfer_receiver_config_guard receiver_config;
  receiver_config.allow();

  auto encode_declare = [](const std::string &epoch_id, uint64_t sequence,
                           uint64_t token) {
    Preserve_trx_transfer_frame frame;
    frame.type = Preserve_trx_transfer_frame_type::DECLARE_TOKEN;
    frame.sequence = sequence;
    frame.epoch_id = epoch_id;
    frame.token = token;
    std::string encoded;
    EXPECT_EQ(Preserve_trx_transfer_status::OK,
              preserve_trx_transfer_encode_frame(frame, &encoded));
    return encoded;
  };

  const std::string epoch_id = "epoch-different-token-apply-barrier";
  const std::string first_payload = encode_declare(epoch_id, 1, 920);
  const std::string second_payload = encode_declare(epoch_id, 2, 921);
  Local_file_preserved_trx_carrier carrier(m_dir);
  Preserved_trx_store store(&carrier);
  Preserve_trx_transfer_receiver_registry registry;

  Transfer_receiver_blocking_after_admission_probe probe;
  std::atomic<int> first_status{
      static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN)};
  std::thread first_thread([&] {
    first_status.store(static_cast<int>(
        preserve_trx_transfer_handle_receiver_payload_batch(
            m_dir, {first_payload}, &store, &registry, 1, 1, nullptr,
            transfer_receiver_blocking_after_admission_probe, &probe)));
  });
  {
    std::unique_lock<std::mutex> lock(probe.mutex);
    ASSERT_TRUE(probe.condition.wait_for(
        lock, std::chrono::seconds(1), [&] { return probe.entered; }));
  }

  std::atomic<int> second_status{
      static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN)};
  std::thread second_thread([&] {
    second_status.store(static_cast<int>(
        preserve_trx_transfer_handle_receiver_payload_batch(
            m_dir, {second_payload}, &store, &registry, 1, 1)));
  });
  for (uint attempt = 0;
       attempt < 100 &&
       second_status.load() ==
           static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN);
       ++attempt) {
    my_sleep(1000);
  }
  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::OK),
            second_status.load());

  {
    std::lock_guard<std::mutex> lock(probe.mutex);
    probe.released = true;
  }
  probe.condition.notify_all();
  first_thread.join();
  second_thread.join();
  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::OK),
            first_status.load());
}

TEST_F(PreserveSnapshotTest,
       TransferReceiverPayloadRetryReusesSameTokenApplyReservation) {
  Transfer_receiver_config_guard receiver_config;
  receiver_config.allow();
  const std::string epoch_id = "epoch-same-token-apply-retry";
  const uint64_t token = 922;

  Preserve_trx_transfer_frame declare;
  declare.type = Preserve_trx_transfer_frame_type::DECLARE_TOKEN;
  declare.sequence = 1;
  declare.epoch_id = epoch_id;
  declare.token = token;
  std::string encoded_declare;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_encode_frame(declare, &encoded_declare));

  Preserve_trx_transfer_frame abort;
  abort.type = Preserve_trx_transfer_frame_type::ABORT;
  abort.sequence = 2;
  abort.epoch_id = epoch_id;
  abort.token = token;
  abort.reason = "retry-complete";
  std::string encoded_abort;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_encode_frame(abort, &encoded_abort));

  Local_file_preserved_trx_carrier carrier(m_dir);
  Preserved_trx_store store(&carrier);
  Preserve_trx_transfer_receiver_registry registry;
  const auto fail_after_admission =
      [](void *, bool contains_commit_epoch) {
        return contains_commit_epoch
                   ? Preserve_trx_transfer_status::INVALID_ARGUMENT
                   : Preserve_trx_transfer_status::IO_ERROR;
      };
  ASSERT_EQ(Preserve_trx_transfer_status::IO_ERROR,
            preserve_trx_transfer_handle_receiver_payload_batch(
                m_dir, {encoded_declare}, &store, &registry, 1, 1, nullptr,
                fail_after_admission, nullptr));

  std::atomic<int> abort_status{
      static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN)};
  std::thread abort_thread([&] {
    abort_status.store(static_cast<int>(
        preserve_trx_transfer_handle_receiver_payload_batch(
            m_dir, {encoded_abort}, &store, &registry, 1, 1)));
  });
  my_sleep(20000);
  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::ACK_UNCERTAIN),
            abort_status.load());

  EXPECT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_handle_receiver_payload_batch(
                m_dir, {encoded_declare}, &store, &registry, 1, 1));
  abort_thread.join();
  EXPECT_EQ(static_cast<int>(Preserve_trx_transfer_status::OK),
            abort_status.load());

  Preserve_trx_transfer_receiver_record record;
  ASSERT_TRUE(registry.lookup(epoch_id, token, &record));
  EXPECT_EQ(Preserve_trx_transfer_receiver_state::ABORTED, record.state);
}

TEST_F(PreserveSnapshotTest,
       TransferReceiverSealDoesNotPublishProjectionBeforeCommitEpoch) {
  Transfer_codec_context_guard codec_guard;
  const uint64_t seal_ready_before =
      preserve_trx_transfer_receiver_seal_prewarm_success_tokens_status();
  Transfer_receiver_config_guard receiver_config;
  receiver_config.allow();

  Preserve_snapshot_metadata meta = metadata();
  meta.token = test_transfer_token_string(916);
  Preserved_trx_bundle bundle;
  Preserved_trx_bundle_build_input input;
  input.metadata = meta;
  input.emit_no_cache_binlog_mode_metadata = true;
  ASSERT_EQ(Preserve_snapshot_status::OK,
            build_preserved_trx_bundle(input, &bundle));

  Preserve_trx_transfer_manifest manifest;
  std::vector<Preserve_trx_transfer_object_payload> objects;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_build_portable_objects(
                "epoch-seal-prepublish", bundle,
                916, &manifest, &objects));

  Local_file_preserved_trx_carrier carrier(m_dir);
  Preserved_trx_store store(&carrier);
  Preserve_trx_transfer_receiver_registry registry;
  uint64_t sequence = 1;

  Preserve_trx_transfer_frame declare;
  declare.type = Preserve_trx_transfer_frame_type::DECLARE_TOKEN;
  declare.sequence = sequence++;
  declare.epoch_id = manifest.epoch_id;
  declare.token = manifest.token;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_apply_receiver_frame(
                m_dir, declare, &store, &registry, 300, nullptr));

  std::string manifest_payload;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_encode_manifest(manifest, &manifest_payload));
  Preserve_trx_transfer_frame begin;
  begin.type = Preserve_trx_transfer_frame_type::BEGIN;
  begin.sequence = sequence++;
  begin.epoch_id = manifest.epoch_id;
  begin.token = manifest.token;
  begin.manifest_payload = manifest_payload;
  ASSERT_EQ(Preserve_trx_transfer_status::OK,
            preserve_trx_transfer_apply_receiver_frame(
                m_dir, begin, &store, &registry, 300, nullptr));

  for (const Preserve_trx_transfer_object_payload &object : objects) {
    Preserve_trx_transfer_frame chunk;
    chunk.type = Preserve_trx_transfer_frame_type::OBJECT_CHUNK;
    chunk.sequence = sequence++;
    chunk.epoch_id = manifest.epoch_id;
    chunk.token = manifest.token;
    chunk.object_id = object.descriptor.object_id;
    chunk.chunk_payload = object.payload;
    ASSERT_EQ(Preserve_trx_transfer_status::OK,
              preserve_trx_transfer_apply_receiver_frame(
                  m_dir, chunk, &store, &registry, 300, nullptr));

    Preserve_trx_transfer_frame seal;
    seal.type = Preserve_trx_transfer_frame_type::SEAL_OBJECT;
    seal.sequence = sequence++;
    seal.epoch_id = manifest.epoch_id;
    seal.token = manifest.token;
    seal.object_id = object.descriptor.object_id;
    ASSERT_EQ(Preserve_trx_transfer_status::OK,
              preserve_trx_transfer_apply_receiver_frame(
                  m_dir, seal, &store, &registry, 300, nullptr));
  }

  for (uint attempt = 0; attempt < 100; ++attempt) {
    if (preserve_trx_transfer_receiver_seal_prewarm_success_tokens_status() >
        seal_ready_before) {
      break;
    }
    my_sleep(10000);
  }
  ASSERT_GT(preserve_trx_transfer_receiver_seal_prewarm_success_tokens_status(),
            seal_ready_before);

  Preserved_trx_carrier_token_state state;
  ASSERT_EQ(Preserved_trx_carrier_status::OK,
            carrier.token_state(test_transfer_token_string(manifest.token),
                                &state));
  EXPECT_FALSE(state.snapshot);
  EXPECT_FALSE(state.standby_pending);
}

